function encounterRegion(){return state.scene==='pass'?'pass':state.scene==='world'?(state.player?.x>1135?'east':'west'):'forest'}
function randomInt(min,max){return min+Math.floor(Math.random()*(max-min+1))}
function regionalEnemies(region=encounterRegion()){const packs=REGION_PACKS[region],pack=packs[randomInt(0,packs.length-1)];return pack.map(([name,ar,hp,attack,defense,color,xp,speed,goldMin,goldMax])=>{const strength=.9+Math.random()*.2,e=makeEnemy(name,ar,Math.round(hp*strength),Math.round(attack*strength),defense,color,Math.round(xp*strength),speed,0);return Object.assign(e,{region,goldMin,goldMax})})}
function bossLoot(enemy,min,max){return Object.assign(enemy,{goldMin:min,goldMax:max})}
function battleGold(enemies){return enemies.reduce((total,e)=>{if(e.goldAward===undefined)e.goldAward=Number.isFinite(e.goldMin)?randomInt(e.goldMin,e.goldMax):Math.max(0,e.gold||0);return total+e.goldAward},0)}
